dict(when='2026-10-30 00:39',who='International Organization for Migration (@IOMHaiti)',where="X and IOM Displacement Tracking Matrix, Petite Rivière de l'Artibonite and Verrettes",url='https://x.com/IOMHaiti/status/2115936619526287574',text="IOM says 13,912 people (3,316 households) fled armed violence between 19 and 26 Oct in Petite Rivière de l'Artibonite (Bas Coursin 2, L'Amour, La Hatte) and Verrettes (Chanklot). About 62 percent went to Petite Rivière and 38 percent to Verrettes; 77 percent are staying with host families and the rest in 14 sites, four of them new.",evidence='UN agency report (Emergency Tracking Tool 112.1)',other='',links=[['IOM report ETT 112.1', 'https://dtm.iom.int/reports/haiti-emergency-tracking-tool-1121-updates-displacement-following-armed-violence-communes']]),
