 dict(when='2026-10-23 21:05',who='Jake Johnston (@JakobJohnston), Haiti analyst at CEPR, author of "Aid State"',where="X, English, about 17,000 followers",url='https://x.com/JakobJohnston/status/2113693222912319990',
  text="Says there is very little chance this Salvadoran deployment is a \"rescue\" operation; it seems most likely the four Salvadoran troops were killed in the attack last Sunday, despite official statements claiming otherwise. Adds that rhetoric from foreign leaders is more about a domestic audience than Haiti, and that Bukele has talked about sending troops to Haiti for more than two years.",
  evidence="his own opinion; no source given",other="The Salvadoran military and US Ambassador Waltz say the four survived (see below). Kim Ives of Haïti Liberté relays Chérizier saying all were killed.",links=[]),
 dict(when="2026-10-23 21:00",who="Héctor Rodríguez Pimentel (@HectorRPimentel), former Dominican senator and journalist",where="X, Spanish",url="https://x.com/HectorRPimentel/status/2113692168585908600",
  text="Says Bukele reached Washington on the night of 22 Oct for an urgent meeting with Trump (citing AP), that 100 Salvadoran special forces landed in Port-au-Prince on 22 Oct and 100 more were due that night for 200 in total, that the Salvadoran law changed the mission from medical evacuation to deploying civilian and military personnel, and that Bukele is asking Trump for satellite intelligence and drones over Croix-des-Bouquets, armed helicopters, and UN permission for the GSF to use offensive lethal force. Quotes Trump on Truth Social: \"I look forward to seeing President Bukele of El Salvador on Monday.\"",
  evidence="video, 49 seconds (not yet watched by us); cites AP and the GSF; no named source for the requests Bukele is said to make",other="The Salvadoran law date: Pimentel says 10 Oct; Diario El Mundo (El Salvador) reports it approved 29 Sep, published 30 Sep, in force 2 Oct 2026.",links=[("Diario El Mundo, El Salvador","https://diario.elmundo.sv/nacionales/haiti-lanza-ofensiva-contra-pandillas-tras-secuestro-de-salvadorenos")]),
